							has_global_flag = extradimensional_second_portal_destroyed
							has_global_flag = extradimensional_third_portal_destroyed
						}
					}

					num_ships < 20

					NOR = {
						any_controlled_ship = { is_ship_size = dimensional_portal_ed }
